const pages = $input.all().map(x => x.json);
const devices = pages.flatMap(p => Array.isArray(p.data) ? p.data : []);
const supported = new Set(['router','switch']);
return devices.map(d => {
  const active = d.is_active !== false;
  const supportedType = supported.has(String(d.device_type || '').toLowerCase());
  const permitted = d.ssh_enabled === true || supportedType;
  const validId = typeof d.id === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(d.id);
  const eligible = active && supportedType && permitted && validId && typeof d.ip_address === 'string' && typeof d.hostname === 'string';
  return {json:{id:d.id,hostname:d.hostname,ip_address:d.ip_address,device_type:d.device_type,site:d.site || 'Unspecified',eligible,skip_reason:!active?'inactive':!supportedType?'unsupported_device_type':!permitted?'ssh_backup_disabled':!validId?'invalid_device_id':null}};
});

const source = $('Check Backup Eligibility').item.json;
const r = $json.body ?? $json;
const status = $json.statusCode;
const data = r.data ?? {};
return [{json:{hostname:source.hostname,ip_address:source.ip_address,device_type:source.device_type,site:source.site,eligible:true,backup_id:data.backup?.id ?? r.error?.details?.backup_id ?? null,status:data.success && status < 300 ? 'success' : 'failed',backup_timestamp:data.backup?.completed_at ?? data.backup?.created_at ?? null,checksum:data.backup?.checksum ?? null,changed:data.changed ?? false,automation_log_id:data.automation_log_id ?? null,error_reason:data.success ? null : (r.error?.code ?? 'backup_request_failed')}}];

const rows = $input.all().map(i => i.json);
const successes = rows.filter(r => r.status === 'success');
const failed = rows.filter(r => r.status === 'failed');
const changed = successes.filter(r => r.changed);
const channel = ($env.NETOPS_BACKUP_SUMMARY_CHANNEL || 'none').toLowerCase();
if (!['telegram','email','none'].includes(channel)) throw new Error('Invalid backup summary channel');
const summary = {started_at:$('Capture Scheduled Start').first().json.started_at,completed_at:new Date().toISOString(),execution_id:$('Capture Scheduled Start').first().json.execution_id,total_eligible:rows.filter(r => r.eligible).length,success_count:successes.length,failed_count:failed.length,skipped_count:rows.filter(r => !r.eligible).length,changed_count:changed.length,devices:rows.map(({hostname,ip_address,device_type,site,backup_id,status,backup_timestamp,checksum,changed,error_reason,automation_log_id})=>({hostname,ip_address,device_type,site,backup_id,status,backup_timestamp,checksum,changed,error_reason,automation_log_id})),notification_channel:channel};
summary.notification_text = `NetOps360 backup run\nEligible: ${summary.total_eligible} | Success: ${summary.success_count} | Failed: ${summary.failed_count} | Skipped: ${summary.skipped_count}\nChanged configurations: ${summary.changed_count}`;
return [{json:summary}];

const p = $json.body ?? $json;
const headers = $json.headers ?? {};
const supplied = headers['x-netops-backup-token'] || headers['X-NetOps-Backup-Token'];
const expected = $env.NETOPS_BACKUP_EVENT_TOKEN || '';
if (!expected || typeof supplied !== 'string' || supplied.length !== expected.length || !require('crypto').timingSafeEqual(Buffer.from(supplied),Buffer.from(expected))) throw new Error('Unauthorized backup event');
if (p.event_type !== 'incident.opened' || !p.incident || typeof p.incident.id !== 'string' || typeof p.incident.title !== 'string' || !['critical','warning'].includes(p.incident.severity) || !p.device || typeof p.device.id !== 'string' || typeof p.device.hostname !== 'string' || typeof p.device.ip_address !== 'string') throw new Error('Invalid incident event');
const severity = p.incident.severity;
const supported = ['router','switch'].includes(String(p.device.device_type || '').toLowerCase());
const allowed = (severity === 'critical' && $env.NETOPS_BACKUP_ON_CRITICAL === 'true') || (severity === 'warning' && $env.NETOPS_BACKUP_ON_WARNING === 'true');
if (!supported || !allowed) throw new Error('Incident does not meet the backup policy');
return [{json:{device_id:p.device.id,device:{hostname:p.device.hostname,ip_address:p.device.ip_address,device_type:p.device.device_type,site:p.device.site || 'Unspecified'},incident_id:p.incident.id,severity}}];

const source = $('Authenticate and Validate Incident').item.json;
const r = $json.body ?? $json;
return [{json:{success:Boolean(r.data?.success),duplicate:Boolean(r.data?.duplicate),incident_id:source.incident_id,device:source.device,backup:r.data?.backup ?? null,automation_log_id:r.data?.automation_log_id ?? null,error:r.error?.code ?? null}}];
